UPDATE TB_DATA_MODEL_ATTR SET PK_YN = #{pkYn}
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND OBJ_NM = #{objNm}
  AND ATTR_NM = #{attrNm}

UPDATE TB_DATA_MODEL_ATTR SET
	 FK_YN = #{fkYn}
	,FK_PARENT_OBJ_NM = #{fkParentObjNm, jdbcType=VARCHAR}
	,FK_PARENT_ATTR_NM = #{fkParentAttrNm, jdbcType=VARCHAR}
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND OBJ_NM = #{objNm}
  AND ATTR_NM = #{attrNm}

UPDATE TB_DATA_MODEL_ATTR SET ATTR_ORD = #{attrOrder, jdbcType=SMALLINT}
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND OBJ_NM = #{objNm}
  AND ATTR_NM = #{attrNm}

