SELECT COUNT(*) FROM TB_DATA_MODEL_ATTR
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND OBJ_NM = #{objNm}
  AND ATTR_ORD = #{attrOrder}
  AND ATTR_NM <> #{selfAttrNm}
  AND USE_YN = 'Y'

SELECT ATTR_NM FROM TB_DATA_MODEL_ATTR
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND OBJ_NM = #{objNm}
  AND ATTR_ORD = #{attrOrder}
  AND ATTR_NM <> #{selfAttrNm}
  AND USE_YN = 'Y'

mapper.update:
UPDATE TB_DATA_MODEL_ATTR SET
	 ATTR_NM   = #{newAttrNm, jdbcType=VARCHAR}
	,DATA_TYPE = #{dataType, jdbcType=VARCHAR}
	,DATA_LEN  = #{dataLen, jdbcType=BIGINT}
	,DATA_DECIMAL_LEN = #{dataDecimalLen, jdbcType=SMALLINT}
	,ATTR_ORD  = #{attrOrder, jdbcType=SMALLINT}
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND OBJ_NM = #{objNm}
  AND ATTR_NM = #{origAttrNm}

UPDATE TB_DATA_MODEL_INDEX SET COLUMN_NM = #{newAttrNm}
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND TABLE_NM = #{objNm}
  AND COLUMN_NM = #{origAttrNm}

UPDATE TB_DATA_MODEL_CONSTRAINT SET COLUMN_NM = #{newAttrNm}
WHERE DM_ID = #{dataModelId}
  AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND TABLE_NM = #{objNm}
  AND COLUMN_NM = #{origAttrNm}

UPDATE TB_DATA_MODEL_CONSTRAINT SET REF_COLUMN_NM = #{newAttrNm}
WHERE DM_ID = #{dataModelId}
  AND REF_OWNER = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
  AND REF_TABLE_NM = #{objNm}
  AND REF_COLUMN_NM = #{origAttrNm}

UPDATE TB_DATA_MODEL_ATTR SET FK_PARENT_ATTR_NM = #{newAttrNm}
WHERE DM_ID = #{dataModelId}
  AND FK_PARENT_OBJ_NM = #{objNm}
  AND FK_PARENT_ATTR_NM = #{origAttrNm}

UPDATE TB_DATA_MODEL_ATTR SET
	 ATTR_NM          = #{attrNm, jdbcType=VARCHAR}
	,ATTR_NM_KR       = #{attrNmKr, jdbcType=VARCHAR}
	,DATA_TYPE        = #{dataType, jdbcType=VARCHAR}
	,DATA_LEN         = #{dataLen, jdbcType=BIGINT}
	,DATA_DECIMAL_LEN = #{dataDecimalLen, jdbcType=SMALLINT}
	,TERMS_STND_YN    = #{termsStndYn, jdbcType=VARCHAR}
	,DOMAIN_STND_YN   = #{domainStndYn, jdbcType=VARCHAR}
	,WORD_LST         = #{wordLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
	,WORD_STND_LST    = #{wordStndLst, typeHandler=com.ndata.common.handler.ArrayTypeHandler}
WHERE DM_ID = #{dataModelId} AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '') AND OBJ_NM = #{objNm} AND ATTR_NM = #{origAttrNm}

UPDATE TB_DATA_MODEL_OBJ O SET OBJ_ATTR_CNT = (
	SELECT COUNT(*) FROM TB_DATA_MODEL_ATTR A
	WHERE A.DM_ID = O.DM_ID AND A.OBJ_OWNER = O.OBJ_OWNER AND A.OBJ_NM = O.OBJ_NM
)
WHERE O.DM_ID = #{dataModelId} AND O.OBJ_NM = #{objNm}

mapper.select:
SELECT COALESCE(MAX(ATTR_ORD), 0) FROM TB_DATA_MODEL_ATTR
WHERE DM_ID = #{dataModelId} AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '') AND OBJ_NM = #{objNm}
  AND USE_YN = 'Y'

SELECT COALESCE(MAX(CAST(SUBSTRING(ATTR_NM FROM 9) AS INTEGER)), 0)
  FROM TB_DATA_MODEL_ATTR
 WHERE DM_ID = #{dataModelId}
   AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
   AND OBJ_NM = #{objNm}
   AND ATTR_NM ~ '^TMP_COL_[0-9]+$'

SELECT OBJ_OWNER as objOwner, OBJ_NM as objNm, ATTR_NM as attrNm
  FROM TB_DATA_MODEL_ATTR
 WHERE DM_ID = #{dataModelId}
   AND FK_PARENT_OBJ_NM = #{objNm} AND FK_PARENT_ATTR_NM = #{attrNm}
   AND USE_YN = 'Y'

