DELETE FROM TB_DATA_MODEL_CONSTRAINT
 WHERE DM_ID = #{dataModelId}
   AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
   AND TABLE_NM = #{objNm}
   AND CONSTRAINT_NM IN (
     SELECT CONSTRAINT_NM FROM TB_DATA_MODEL_CONSTRAINT
     WHERE DM_ID = #{dataModelId}
       AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
       AND TABLE_NM = #{objNm} AND COLUMN_NM = #{attrNm}
   )

DELETE FROM TB_DATA_MODEL_INDEX
 WHERE DM_ID = #{dataModelId}
   AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
   AND TABLE_NM = #{objNm}
   AND INDEX_NM IN (
     SELECT INDEX_NM FROM TB_DATA_MODEL_INDEX
     WHERE DM_ID = #{dataModelId}
       AND COALESCE(OBJ_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
       AND TABLE_NM = #{objNm} AND COLUMN_NM = #{attrNm}
   )

DELETE FROM TB_DATA_MODEL_CONSTRAINT
 WHERE DM_ID = #{dataModelId}
   AND (OBJ_OWNER, TABLE_NM, CONSTRAINT_NM) IN (
     SELECT OBJ_OWNER, TABLE_NM, CONSTRAINT_NM FROM TB_DATA_MODEL_CONSTRAINT
     WHERE DM_ID = #{dataModelId}
       AND COALESCE(REF_OWNER, '') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR}, ''), '')
       AND REF_TABLE_NM = #{objNm} AND REF_COLUMN_NM = #{attrNm}
   )

