UPDATE TB_DATA_MODEL_ATTR SET FK_PARENT_OBJ_NM = NULL, FK_PARENT_ATTR_NM = NULL, FK_YN = 'N'
 WHERE DM_ID = #{dataModelId}
   AND FK_PARENT_OBJ_NM = #{objNm} AND FK_PARENT_ATTR_NM = #{attrNm}
